# IUPAC DNA codes mapping for sequence generation
IUPAC_DNA_TO_BASES = {
    'A': ['A'], 'C': ['C'], 'G': ['G'], 'T': ['T'], 'R': ['A', 'G'],
    'Y': ['C', 'T'], 'S': ['G', 'C'], 'W': ['A', 'T'], 'K': ['G', 'T'],
    'M': ['A', 'C'], 'B': ['C', 'G', 'T'], 'D': ['A', 'G', 'T'],
    'H': ['A', 'C', 'T'], 'V': ['A', 'C', 'G'], 'N': ['A', 'C', 'G', 'T']
}

IUPAC_EXPAND = {k: frozenset(v) for k, v in IUPAC_DNA_TO_BASES.items()}
IUPAC_COLLAPSE = {v: k for k, v in IUPAC_EXPAND.items()}

# IUPAC DNA codes mapping for regex conversion
IUPAC_DNA_TO_REGEX = {
    'A': 'A', 'C': 'C', 'G': 'G', 'T': 'T', 'R': '[AG]', 'Y': '[CT]',
    'S': '[GC]', 'W': '[AT]', 'K': '[GT]', 'M': '[AC]', 'B': '[CGT]',
    'D': '[AGT]', 'H': '[ACT]', 'V': '[ACG]', 'N': '[ATGC]'
}

# IUPAC DNA codes for reverse complement
IUPAC_COMPLEMENT = {
    'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C',
    'R': 'Y', 'Y': 'R', 'S': 'S', 'W': 'W',
    'K': 'M', 'M': 'K', 'B': 'V', 'V': 'B',
    'D': 'H', 'H': 'D', 'N': 'N'
}
_COMPLEMENT = str.maketrans("".join(IUPAC_COMPLEMENT), "".join(IUPAC_COMPLEMENT.values()))


# %% ../nbs/01_utils.ipynb #74913579
def calculate_log2fc(df, reference_column='MFDpir', count_threshold=20, pseudocount=1):
    """
    Filters a DataFrame, normalizes columns by sum, calculates log2 fold change
    relative to a reference column, and drops the reference column.

    Args:
        df (pd.DataFrame): Input DataFrame (rows=features, columns=samples). NaN counts as 0.
        reference_column (str): Name of the reference sample column.
        count_threshold (int): a feature is kept when its reference count is strictly above this.
        pseudocount (float): Value added to the raw counts, before normalisation.

    Returns:
        pd.DataFrame: DataFrame with log2 fold change values. None if reference
                      column is missing. Empty DataFrame if all rows are filtered out.
    """

    df = df.replace(np.nan,0)
    if reference_column not in df.columns:
        print(f"Error: Reference column '{reference_column}' not found in DataFrame.")
        return None

    # 1. Filter rows
    df_filtered = df[df[reference_column] > count_threshold].copy()
    if df_filtered.empty:
        print("DataFrame is empty after filtering.")
        return pd.DataFrame()

    # 2. Add the pseudocount to the raw counts, before normalisation.
    df_with_pseudocount = df_filtered + pseudocount

    # 3. Normalise each column by its sum (over the plasmids that passed the filter).
    column_sums = df_with_pseudocount.sum(axis=0)
    df_processed = df_with_pseudocount.div(column_sums, axis=1)

    # Check if reference column still exists (it should)
    if reference_column not in df_processed.columns:
        print(f"Error: Reference column '{reference_column}' lost during processing.")
        return None

    reference_values = df_processed[reference_column]

    # 4. log2 of each sample's share over the reference's share, row by row.
    log2fc_df = np.log2(df_processed.div(reference_values, axis=0))

    # 5. Drop the reference column's own log2FC (which will be ~zeros)
    if reference_column in log2fc_df.columns:
        log2fc_df = log2fc_df.drop(columns=[reference_column])
    else:
        print(f"Warning: Reference column '{reference_column}' not found in log2fc_df for dropping.")

    return log2fc_df

# %% ../nbs/01_utils.ipynb #62be92ea
def score(FCs, thr=-1):
    """Fraction of the plasmids carrying a motif whose log2FC is below `thr`.

    The depletion score, written out plainly. The pipeline computes it inline over whole arrays,
    so nothing in `randseq.core` calls this; it is here to be read, and to score a motif's fold
    changes by hand.

    Args:
        FCs (list): log2 fold changes of the plasmids carrying the motif.
        thr (float): a plasmid is depleted when its log2FC is strictly below this.

    Returns:
        float: the fraction depleted, or 0.0 when no plasmid carries the motif.
    """
    if len(FCs) == 0:
        return 0.0
    return sum([x < thr for x in FCs]) / len(FCs)

# %% ../nbs/01_utils.ipynb #44e4aa1e
def normalise_motif(motif:str):
    """`motif` upper-cased, with each bracketed class written as its IUPAC letter:
    `'[AG]TACNNNNGTG'` -> `'RTACNNNNGTG'`.

    Raises `ValueError` on anything that is neither an IUPAC letter nor a class of A, C, G, T, so
    a misspelt motif fails loudly instead of matching nothing."""
    m, out, i = motif.upper(), [], 0
    while i < len(m):
        if m[i] == '[':
            j = m.find(']', i)
            bases = frozenset(m[i + 1:j]) if j > i else frozenset()
            if not bases or not bases <= IUPAC_EXPAND['N']:
                raise ValueError(f"invalid class in motif {motif!r}")
            out.append(IUPAC_COLLAPSE[bases])
            i = j + 1
        elif m[i] in IUPAC_COMPLEMENT:
            out.append(m[i])
            i += 1
        else:
            raise ValueError(f"{m[i]!r} in motif {motif!r} is not an IUPAC code")
    return "".join(out)


def revcomp(seq:str):
    """Reverse complement of a DNA sequence or an IUPAC motif, upper-cased: `R` becomes `Y`,
    `N` stays `N`. Bracketed classes are accepted and come back as IUPAC letters."""
    if '[' in seq:
        seq = normalise_motif(seq)
    return seq.upper().translate(_COMPLEMENT)[::-1]


# %% ../nbs/01_utils.ipynb #04af769a
_REBASE_MOTIFS = None

def get_rebase_motifs():
    """The REBASE Gold Standard recognition motifs shipped with the package.

    Returns a `set` of IUPAC motif strings (n=983, downloaded 2025-12-03). Used by
    `canonical_motif` to decide which strand to report a motif on. Read once and cached.
    """
    global _REBASE_MOTIFS
    if _REBASE_MOTIFS is None:
        from randseq.data import get_data_dir
        path = os.path.join(get_data_dir(), 'rebase_gold_standard_motifs.txt')
        with open(path) as fh:
            _REBASE_MOTIFS = {line.strip().upper() for line in fh if line.strip()}
    return _REBASE_MOTIFS

# %% ../nbs/01_utils.ipynb #21042f37
def canonical_motif(motif, rebase_motifs=None):
    """Return the strand `motif` should be reported on.

    A motif and its reverse complement describe the same recognition site and always carry the
    same statistics, so exactly one of them should appear in the results. Prefer the strand that
    REBASE uses; if REBASE knows neither (or both), fall back to the alphabetically first strand,
    which is arbitrary but identical on every run.

    Args:
        motif (str): an IUPAC motif, e.g. `'GAGACC'` or `'CACNNNNGTAY'`; bracketed classes
            are accepted and reported as IUPAC letters (`normalise_motif`).
        rebase_motifs (set, optional): Motif set to match against. Defaults to
            `get_rebase_motifs()`. Pass an explicit set to test or to use a different reference.

    Returns:
        str: `motif` or its reverse complement.
    """
    if rebase_motifs is None:
        rebase_motifs = get_rebase_motifs()
    motif = normalise_motif(motif)
    rc = revcomp(motif)
    in_fwd, in_rev = motif in rebase_motifs, rc in rebase_motifs
    if in_fwd and not in_rev:
        return motif
    if in_rev and not in_fwd:
        return rc
    return min(motif, rc)

# %% ../nbs/01_utils.ipynb #3eca7610
def get_lib_seq_context(seqs,left,right):
    """
    Each insert with the vector sequence that flanks it in the plasmid, upper-cased.

    A recognition site can straddle the junction between the random insert and the backbone,
    so motifs are always searched in `left + insert + right`.

    Args:
        seqs (list): the inserts.
        left (str): vector sequence 5' of the insert.
        right (str): vector sequence 3' of the insert.

    Returns:
        list: `left + insert + right` for each insert, in input order.
    """
    left=left.upper()
    right=right.upper()
    lib=[left+r+right for r in seqs]
    return lib

# %% ../nbs/01_utils.ipynb #850fe0d6
def _custom_motif_to_regex(motif):
    """A regex for `motif`: IUPAC letters and bracketed classes become character classes, so
    `'RTAC'` and `'[AG]TAC'` give the same pattern."""
    return "".join(IUPAC_DNA_TO_REGEX[c] for c in normalise_motif(motif))


# %% ../nbs/01_utils.ipynb #16da8b97
def check_specific_matches_broad(specific, broad):
  """
  Whether `specific` matches `broad` position by position, `N` in `broad` matching anything.

  Both strings must be the same length. An `N` in `specific` has no special meaning: it only
  matches an `N` in `broad`.

  Args:
    specific: The string that is being checked.
    broad: The string that contains the pattern, where 'N' is a wildcard.

  Returns:
    True if the 'specific' string matches the 'broad' pattern, False otherwise.
  """
  if len(specific) != len(broad):
    return False

  for spec_char, broad_char in zip(specific, broad):
    if spec_char == broad_char or broad_char == 'N':
      continue
    return False
  return True

def find_broad_in_specific(specific, broad):
  """
  Whether `broad`, or its reverse complement, occurs anywhere in `specific`.

  Each window of `specific` the length of `broad` is compared with
  `check_specific_matches_broad` (`N` in `broad` is a wildcard), forward first, then against
  `revcomp(broad)`. A `broad` longer than `specific` is never found; an empty one always is.

  Args:
    specific: the motif (or sequence) searched in.
    broad: the motif searched for.

  Returns:
    True if 'broad' or its reverse complement is found in 'specific', False otherwise.
  """
  if len(specific) < len(broad):
    return False

  broad_len = len(broad)
  if broad_len == 0:
      return True

  # 1. Check the forward orientation
  is_forward_match = any(check_specific_matches_broad(specific[i:i + broad_len], broad)
                         for i in range(len(specific) - broad_len + 1))

  if is_forward_match:
    return True

  # 2. If no forward match, check the reverse complement orientation
  broad_rev_comp = revcomp(broad)
  is_reverse_match = any(check_specific_matches_broad(specific[i:i + broad_len], broad_rev_comp)
                         for i in range(len(specific) - broad_len + 1))

  return is_reverse_match

# %% ../nbs/01_utils.ipynb #dfbdb2fc
def get_motif_filter_with_context(df, left_context, right_context, motif):
    """Boolean filter selecting sequences that contain `motif`, on either strand.

    The motif is matched against the sequence *with its flanking vector context restored*,
    because a recognition site can straddle the junction between the random insert and the
    backbone; several of the motifs recovered from real data do exactly that.

    Both orientations are searched, since a site and its reverse complement are the same site.
    That is also why a motif and its reverse complement always carry identical statistics, and
    therefore why only one of them should ever be reported (see `canonical_motif`).

    Args:
        df: DataFrame or Series whose **index** holds the DNA sequences.
        left_context, right_context: the vector sequence flanking the insert.
        motif: an IUPAC motif, e.g. `'GGTCTC'` or `'CACNNNNGTAY'`; bracketed classes such as
            `'[AG]TACNNNNGTG'` work too.

    Returns:
        pd.Series: boolean, indexed like `df`. Raises `ValueError` if `motif` is not a valid
        IUPAC motif (`normalise_motif`).
    """
    fwd = re.compile(_custom_motif_to_regex(motif), re.IGNORECASE)
    rev = re.compile(_custom_motif_to_regex(revcomp(motif)), re.IGNORECASE)

    def present(seq):
        full = f"{left_context}{seq}{right_context}"
        return bool(fwd.search(full) or rev.search(full))

    return df.index.to_series().apply(present)

# %% ../nbs/01_utils.ipynb #3e05601c
def _get_filter_for_motif(series, motif, left_context, right_context):
    """`get_motif_filter_with_context` with the argument order used inside the pipeline."""
    return get_motif_filter_with_context(series, left_context, right_context, motif)

# %% ../nbs/01_utils.ipynb #b8aa3df2
def generate_tuple_combinations(a1, a2, b1, b2, c1, c2):
  """
  Every `(a, b, c)` with `a1 <= a <= a2`, `b1 <= b <= b2` and `c1 <= c <= c2`.

  Builds `(d1, spacer, d2)` motif patterns in bulk; `get_patterns` is the usual way to get the
  search space.

  Args:
    a1, a2: range of the first element, both ends included.
    b1, b2: range of the second element, both ends included.
    c1, c2: range of the third element, both ends included.

  Returns:
    list of tuples, in lexicographic order.
  """
  range_a = range(a1, a2 + 1)
  range_b = range(b1, b2 + 1)
  range_c = range(c1, c2 + 1)
  return list(itertools.product(range_a, range_b, range_c))

# %% ../nbs/01_utils.ipynb #a800821a
def filter_symmetric_tuples(list_of_tuples):
    """
    Drop a tuple when its mirror (first and third elements swapped) came earlier in the list.

    `(3, 4, 4)` and `(4, 4, 3)` find the same sites, because the scan reads both strands, so only
    the first one met is kept. A tuple that is its own mirror, such as `(4, 4, 4)`, is kept.

    Args:
        list_of_tuples: A list of tuples, where each tuple contains three integers.

    Returns:
        list: the tuples kept, in input order.
    """
    # The canonical form of a pair is the smaller of a tuple and its mirror.
    seen_canonical_forms = set()
    filtered_list = []
    for tup in list_of_tuples:
        symmetric_tup = (tup[2], tup[1], tup[0])
        canonical_form = min(tup, symmetric_tup)
        if canonical_form in seen_canonical_forms:
            continue
        filtered_list.append(tup)
        seen_canonical_forms.add(canonical_form)
    return filtered_list

# %% ../nbs/01_utils.ipynb #4672972a
def canonical_pattern(pattern):
    """The single form of `pattern` the scan uses.

    Two kinds of spelling describe the same search. A contiguous motif has no gap, so
    `(d1, 0, d2)` is just a run of `d1 + d2` bases: `(3, 0, 3)` and `(0, 0, 6)` are `(6, 0, 0)`.
    And a gapped pattern finds the same sites as its mirror `(d2, spacer, d1)`, because the scan
    reads both strands -- a site of one is the reverse complement of a site of the other. Of a
    mirror pair the one with the shorter first half is kept, `(3, 4, 4)` rather than `(4, 4, 3)`.
    """
    d1, spacer, d2 = (int(x) for x in pattern)
    if spacer == 0:
        return (d1 + d2, 0, 0)
    return min((d1, spacer, d2), (d2, spacer, d1))


def get_patterns(contiguous=(5, 7), halves=(2, 4), max_spacer=8, min_defined=5, max_defined=8):
    """The search space: every motif architecture the scan looks for by default.

    A pattern is `(d1, spacer, d2)` -- defined bases, undefined gap, defined bases. The default
    is the 43-pattern set used in the draft: contiguous sites of 5-7 bases, and gapped sites
    whose halves are 2-4 bases, with 5-8 defined bases in all and a gap of 1-8. It fits
    837 of the 983 distinct motifs in the REBASE Gold Standard set shipped with the package
    (`get_rebase_motifs`).

    The arguments widen it. `get_patterns(contiguous=(4, 8), halves=(2, 5), max_spacer=9)`
    (68 patterns) fits 902; adding `max_defined=9` (77) fits 911, at about 8 times the motifs
    tested (3.6 million against 460,000 on the larger example library). A wider search is not
    free at the default thresholds: on the 21-strain panel the 68-pattern set adds 11 calls the
    draft's Fig 3 does not have -- one-base-longer descriptions of weak or degenerate sites,
    which steps 3 and 4 do not yet catch -- and loses one. It is kept as a test case for
    improving those steps, not as the default.

    Every pattern is returned in its `canonical_pattern` form, ordered by number of defined
    bases, then spacer.
    """
    patterns = {(k, 0, 0) for k in range(contiguous[0], contiguous[1] + 1)}
    for a in range(halves[0], halves[1] + 1):
        for b in range(halves[0], halves[1] + 1):
            if min_defined <= a + b <= max_defined:
                patterns.update(canonical_pattern((a, s, b)) for s in range(1, max_spacer + 1))
    return sorted(patterns, key=lambda p: (p[0] + p[2], p[1], p))

# %% ../nbs/01_utils.ipynb #8bc924dc
def get_custom_motif_presence_in_library(short_sequences_list, left_context, right_context, motif_list):
    """
    Which of `motif_list` each insert carries, searched with its context and on both strands.

    Args:
        short_sequences_list (list): the inserts.
        left_context (str): Left context string to prepend.
        right_context (str): Right context string to append.
        motif_list (list): Motif strings using IUPAC codes (e.g. 'AACNNNNCTTT', 'RTACNNNNGTG')
                           and/or regex character classes (e.g. '[AG]TACNNNNGTG').

    Returns:
        pd.DataFrame: one row per insert, in input order, indexed by the sequence *with its
                      context*; one boolean column per motif. A motif that is empty, not a
                      string, or not a valid regex is all False.
    """
    full_sequences_with_context = get_lib_seq_context(short_sequences_list, left_context, right_context)

    valid_full_sequences = [seq for seq in full_sequences_with_context if isinstance(seq, str)]
    if not valid_full_sequences:
        print("No valid full sequences to process after adding context.")
        return pd.DataFrame()
    presence_data = []

    for full_seq_str in valid_full_sequences:
        row_data = {'full_sequence': full_seq_str}
        for flex_motif_str in motif_list:
            if not isinstance(flex_motif_str, str) or not flex_motif_str:
                row_data[flex_motif_str] = False
                continue
            regex_pattern = _custom_motif_to_regex(flex_motif_str)
            try:
                if re.search(regex_pattern, full_seq_str):
                    row_data[flex_motif_str] = True
                elif re.search(regex_pattern, revcomp(full_seq_str)):
                    row_data[flex_motif_str] = True
                else:
                    row_data[flex_motif_str] = False
            except re.error:
                row_data[flex_motif_str] = False
        presence_data.append(row_data)

    if not presence_data:
        return pd.DataFrame(index=valid_full_sequences, columns=motif_list)

    presence_df = pd.DataFrame(presence_data)
    if 'full_sequence' in presence_df.columns:
        presence_df = presence_df.set_index('full_sequence')

    return presence_df

# %% ../nbs/01_utils.ipynb #25b089de
def get_log2fc_distribution_by_motif(log2fc_df, left_context, right_context, motif_list, sample_columns=None):
    """
    Label each plasmid by the motif it carries (or 'Other') and reshape to long format, for
    comparing or plotting the log2FC distribution of each motif.

    Args:
        log2fc_df (pd.DataFrame): DataFrame of log2 fold change values, indexed by short
                                   sequence (rows=features, columns=samples).
        left_context (str): Left context string to prepend before motif search.
        right_context (str): Right context string to append before motif search.
        motif_list (list): motifs as in `get_custom_motif_presence_in_library`. A plasmid
                            carrying several is labelled with the LAST of them in motif_list,
                            the same precedence as `plotting.plot_motif_depletion`.
        sample_columns (list, optional): Subset of columns (samples) from log2fc_df to include.
                                          Defaults to all columns.

    Returns:
        pd.DataFrame: Long-format DataFrame with columns ['sequence', 'Motif_Category',
                      'sample', 'log2fc']. 'Motif_Category' is one of motif_list or 'Other'.
                      None if motif presence could not be computed.
    """
    if sample_columns is None:
        sample_columns = log2fc_df.columns.tolist()

    # Positionally aligned with log2fc_df.index (get_lib_seq_context preserves order).
    presence_df = get_custom_motif_presence_in_library(
        log2fc_df.index.tolist(), left_context, right_context, motif_list
    )

    if presence_df.empty:
        print("Error: could not compute motif presence.")
        return None

    df = log2fc_df[sample_columns].copy()
    df['Motif_Category'] = 'Other'

    for motif in motif_list:
        df.loc[presence_df[motif].values, 'Motif_Category'] = motif

    index_name = df.index.name or 'index'
    long_df = (
        df.reset_index()
          .melt(id_vars=[index_name, 'Motif_Category'], value_vars=sample_columns,
                var_name='sample', value_name='log2fc')
          .rename(columns={index_name: 'sequence'})
    )

    return long_df

# %% ../nbs/01_utils.ipynb #13ad0a45
def benjamini_hochberg(pvalues):
    """BH-adjusted q-values. The scan tests every motif of every pattern, so the number of
    tests is large and sample-specific; correcting for it is not optional."""
    p = np.asarray(pvalues, dtype=float)
    n = len(p)
    if n == 0:
        return p
    order = np.argsort(p)
    ranked = p[order] * n / np.arange(1, n + 1)
    ranked = np.minimum.accumulate(ranked[::-1])[::-1]
    out = np.empty(n)
    out[order] = np.clip(ranked, 0, 1)
    return out

# %% ../nbs/01_utils.ipynb #6811f6cf
def motif_pvalues(num_sequences, fraction_depleted, background):
    """P(at least this many of n plasmids depleted | null), per motif.

    `background` is the null depletion rate: one per motif -- the mean `plasmid_background` of
    its carriers -- or a single rate for all. The depleted count is recovered as
    `round(fraction_depleted * num_sequences)`. Vectorized over a whole score table; the cost is
    negligible beside the scan itself. A rate of 0 gives p = 0 to any motif with a depleted
    plasmid and 1 to the others.
    """
    n = np.asarray(num_sequences, dtype=np.int64)
    k = np.rint(np.asarray(fraction_depleted, dtype=float) * n).astype(np.int64)
    return binom.sf(k - 1, n, background)

# %% ../nbs/01_utils.ipynb #0812b04b
def plasmid_background(sequences, log2fc, log2fc_thr=-1):
    """Each plasmid's background: the fraction of plasmids with a similar insert GC content that
    are depleted in this sample.

    Plasmids are split into deciles of insert GC (`pd.qcut`); every plasmid gets its decile's
    rate of log2FC below `log2fc_thr`. A motif's null depletion rate is the mean over its
    carriers, which `motif_pvalues` tests against.

    Args:
        sequences (list): the inserts, without the vector flanks.
        log2fc (array-like): log2 fold change per insert, in the same order (centred, as
            `find_restricted_motifs` uses it).
        log2fc_thr (float): a plasmid is depleted below this.

    Returns:
        np.ndarray: one rate per plasmid, strictly between 0 and 1.
    """
    gc = np.array([(s.count("G") + s.count("C")) / len(s) for s in sequences])
    # qcut gives NaN only when every edge coincides -- one GC content for the whole library,
    # which is then one bin.
    decile = pd.Series(pd.qcut(gc, 10, labels=False, duplicates="drop")).fillna(0)
    depleted = pd.Series(np.asarray(log2fc, dtype=float) < log2fc_thr)
    rate = np.clip(depleted.groupby(decile).transform("mean").to_numpy(), 1e-6, 1 - 1e-6)
    # Rounded to a multiple of 2**-20 so that a sum over carriers is exact in any order: the
    # scan, its numba threads and `annotate_significance` add the same rates in different orders,
    # and the q-value lookup recognises a motif's test by its p-value, to the last bit.
    return np.round(rate * 2 ** 20) / 2 ** 20

# %% ../nbs/01_utils.ipynb #17a297ed
_N_SET = frozenset('ACGT')


def _raw_distance(m1: str, m2: str) -> int:
    """
    Positional mismatch count between two same-length motifs.
    Positions where either motif is N (fully ambiguous) are skipped.
    Returns -1 for different lengths.
    """
    if len(m1) != len(m2):
        return -1
    dist = 0
    for a, b in zip(m1, m2):
        sa = IUPAC_EXPAND.get(a, frozenset())
        sb = IUPAC_EXPAND.get(b, frozenset())
        if sa == _N_SET or sb == _N_SET:
            continue
        if sa != sb:
            dist += 1
    return dist


def motif_distance(m1: str, m2: str, consider_rc: bool = True) -> tuple[int, bool]:
    """
    Minimum mismatch distance between m1 and m2, optionally also comparing m1
    to the reverse complement of m2 (because RM sites are strand-independent).
    Positions where either motif has N are not counted, and two different IUPAC codes count as
    one mismatch (`R` vs `A` included).

    Returns (distance, used_rc): distance is -1 if lengths differ; used_rc is
    True if the reverse complement of m2 gave the shorter distance.
    """
    d_fwd = _raw_distance(m1, m2)
    if not consider_rc or d_fwd == -1:
        return d_fwd, False

    d_rc = _raw_distance(m1, revcomp(m2))

    if d_rc < d_fwd:
        return d_rc, True
    return d_fwd, False


def merge_motifs(motifs: list[str]) -> str:
    """
    Merge a list of same-length motifs (already in a consistent orientation)
    into a single IUPAC string by taking the union of nucleotide sets per position.
    """
    out = []
    for i in range(len(motifs[0])):
        union = frozenset()
        for m in motifs:
            union = union | IUPAC_EXPAND.get(m[i], frozenset())
        out.append(IUPAC_COLLAPSE.get(union, 'N'))
    return ''.join(out)

# %% ../nbs/01_utils.ipynb #a22f3fdc
def _connected_components(n_nodes: int,
                          edges: list[tuple[int, int]]) -> list[list[int]]:
    """Union-find connected components over integer node indices 0..n_nodes-1."""
    parent = list(range(n_nodes))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv

    comps = {}
    for i in range(n_nodes):
        comps.setdefault(find(i), []).append(i)
    return list(comps.values())


def _assign_orientations(comp: list[int],
                         adj: dict[int, list[tuple[int, bool]]]) -> dict[int, bool]:
    """
    BFS from the first node of a component to assign a consistent orientation
    (forward / RC) to every other node, propagating along edges.

    adj[u] = [(v, used_rc), ...]  - used_rc=True means rc(m_v) was closer to m_u.
    Orientation logic for edge (u -> v, used_rc=r): orient[v] = orient[u] XOR r,
    i.e. if m_v must be flipped to align to m_u and m_u is already flipped,
    m_v ends up back in forward orientation.
    """
    orientation = {comp[0]: False}
    queue = deque([comp[0]])
    while queue:
        u = queue.popleft()
        for v, used_rc in adj.get(u, []):
            if v not in orientation:
                orientation[v] = orientation[u] ^ used_rc
                queue.append(v)
    # Safety net for nodes not reached from comp[0] (shouldn't happen)
    for node in comp:
        orientation.setdefault(node, False)
    return orientation

# %% ../nbs/01_utils.ipynb #2bee3446
def find_iupac_equivalent_motifs(
    df: pd.DataFrame,
    max_mismatches: int = 2,
    motif_col: str = 'motif',
    sample_col: str = None,
    consider_rc: bool = True,
) -> pd.DataFrame:
    """
    Find motifs that differ by at most *max_mismatches* nucleotides and collapse
    them with IUPAC ambiguity codes (within each sample if *sample_col* is given).

    Rules:
    - Only motifs of the same length are compared.
    - N positions are skipped when counting mismatches.
    - When consider_rc=True (default), dist(A, B) = min(dist(A,B), dist(A,rc(B))).
      If rc(B) was closer, B is flipped before merging so all motifs in a group
      share a consistent strand orientation.
    - Groups are found via connected components (transitivity: A~B and B~C
      -> all three merged even if A and C are > max_mismatches apart).
    - The merged motif is spelled on the strand of the group's first row in `df`.

    Args:
        df: DataFrame with at least *motif_col*, e.g. the flexible motifs returned by
            find_restricted_motifs. Optional num_sequences / avg_log2fc /
            fraction_depleted columns are aggregated per group.
        max_mismatches: 1 or 2 recommended.
        motif_col: column containing motif sequences.
        sample_col: column with the sample / strain identifier; None treats the
            whole df as one sample.
        consider_rc: whether to also compare against the reverse complement.

    Returns:
        DataFrame with one row per merged group (including singletons, n_merged == 1):
        [sample_col,] merged_motif, original_motifs, original_motifs_oriented,
        n_merged, max_pairwise_mismatches, rc_used, and when available
        total_sequences (sum), avg_log2fc_weighted (weighted by num_sequences when present)
        and avg_fraction_depleted (unweighted mean).
    """
    records = []
    groups = df.groupby(sample_col, sort=False) if sample_col else [(None, df)]

    for sample, grp in groups:
        grp = grp.reset_index(drop=True)
        motifs = grp[motif_col].str.upper().tolist()

        # Group row indices by motif length
        by_len = {}
        for i, m in enumerate(motifs):
            by_len.setdefault(len(m), []).append(i)

        for row_idxs in by_len.values():
            sub_motifs = [motifs[i] for i in row_idxs]
            n = len(sub_motifs)

            # Build edge list; track RC usage and build adjacency for BFS
            edges = []
            pairwise_dist = {}
            adj = {k: [] for k in range(n)}  # adj[u] = [(v, used_rc), ...], bidirectional

            for i, j in combinations(range(n), 2):
                d, used_rc = motif_distance(sub_motifs[i], sub_motifs[j], consider_rc=consider_rc)
                if d != -1 and 0 < d <= max_mismatches:
                    edges.append((i, j))
                    pairwise_dist[(i, j)] = d
                    adj[i].append((j, used_rc))
                    adj[j].append((i, used_rc))  # symmetric: rc(rc(m)) = m

            for comp in _connected_components(n, edges):
                # Put all motifs of the component on the same strand before merging
                orientations = _assign_orientations(comp, adj)
                oriented_motifs = [revcomp(sub_motifs[k]) if orientations[k] else sub_motifs[k]
                                   for k in comp]
                raw_mots = [sub_motifs[k] for k in comp]

                max_d = 0
                for a, b in combinations(sorted(comp), 2):
                    max_d = max(max_d, pairwise_dist.get((a, b), 0))

                comp_rows = grp.iloc[[row_idxs[k] for k in comp]]

                rec = {sample_col: sample} if sample_col else {}
                rec.update({
                    'merged_motif':             merge_motifs(oriented_motifs),
                    'original_motifs':          ' | '.join(sorted(set(raw_mots))),
                    'original_motifs_oriented': ' | '.join(sorted(set(oriented_motifs))),
                    'n_merged':                 len(set(raw_mots)),
                    'max_pairwise_mismatches':  max_d,
                    'rc_used':                  any(orientations[k] for k in comp),
                })

                if 'num_sequences' in grp.columns:
                    weights = comp_rows['num_sequences'].to_numpy(dtype=float)
                    rec['total_sequences'] = int(weights.sum())
                else:
                    weights = np.ones(len(comp_rows))

                if 'avg_log2fc' in grp.columns:
                    rec['avg_log2fc_weighted'] = float(
                        np.average(comp_rows['avg_log2fc'].to_numpy(dtype=float), weights=weights))

                if 'fraction_depleted' in grp.columns:
                    rec['avg_fraction_depleted'] = float(comp_rows['fraction_depleted'].mean())

                records.append(rec)

    return pd.DataFrame(records)
